def read_source_bytes(repo_root: str, file_path: str, max_bytes: int | None = None) -> tuple[str, bytes]:
    """Shared path checks; optional byte bound for whole-file source scanning."""
    if max_bytes is not None and (type(max_bytes) is not int or max_bytes < 1):
        raise SourceReadError("max_bytes must be a positive integer.")
    if not file_path or "\x00" in file_path:
        raise SourceReadError("A repository-relative file path is required.")
    relative = Path(file_path)
    if relative.is_absolute() or PureWindowsPath(file_path).drive or ".." in relative.parts:
        raise SourceReadError("Only repository-relative paths without '..' are allowed.")
    if any(part.lower() == ".git" for part in relative.parts):
        raise SourceReadError("Git metadata cannot be read through this tool.")
    try:
        root = Path(repo_root).resolve(strict=True)
        if not root.is_dir():
            raise SourceReadError("Repository directory not found.")
        candidate = root
        for part in relative.parts:
            candidate /= part
            if candidate.is_symlink():
                raise SourceReadError("Symbolic links cannot be read through this tool.")
        path = candidate.resolve(strict=True)
        if not path.is_relative_to(root) or not path.is_file():
            raise SourceReadError("Path must point to a regular file inside the repository.")
        with path.open("rb") as source:
            data = source.read() if max_bytes is None else source.read(max_bytes + 1)
    except (OSError, RuntimeError) as exc:
        raise SourceReadError("File is missing or cannot be read.") from exc
    if max_bytes is not None and len(data) > max_bytes:
        raise SourceReadError("File exceeds the source scanning byte limit.")
    return path.relative_to(root).as_posix(), data

def read_source_file(
    repo_root: str, file_path: str, start_line: int = 1, end_line: int | None = None
) -> SourceExcerpt:
    if type(start_line) is not int or start_line < 1:
        raise SourceReadError("start_line must be a positive integer.")
    if end_line is not None and (type(end_line) is not int or end_line < start_line):
        raise SourceReadError("end_line must be an integer greater than or equal to start_line.")
    name, data = read_source_bytes(repo_root, file_path)
    if b"\x00" in data:
        raise SourceReadError("Binary files cannot be read as source text.")
    lines = data.decode("utf-8", errors="ignore").splitlines()
    digest = hashlib.sha256(data).hexdigest()
    if not lines:
        if start_line != 1 or end_line is not None:
            raise SourceReadError("The file is empty and has no line range.")
        return SourceExcerpt(name, 0, 0, 0, "", digest)
    if start_line > len(lines):
        raise SourceReadError(f"start_line exceeds the file length ({len(lines)} lines).")
    stop = min(end_line if end_line is not None else len(lines), len(lines))
    selected = []
    used = 0
    partial = False
    for line in lines[start_line - 1:stop]:
        remaining = MAX_READ_CHARS - used
        if remaining <= 0:
            break
        selected.append(line[:remaining])
        used += len(selected[-1]) + 1
        if len(selected[-1]) < len(line):
            partial = True
            break
    actual_end = start_line + len(selected) - 1
    return SourceExcerpt(
        name, start_line, actual_end, len(lines), "\n".join(selected), digest,
        truncated=partial or actual_end < stop, partial_last_line=partial,
    )

def read(self, file_path, start_line=1, end_line=None):
    snapshot = load_snapshot(self.repo_root)
    if snapshot.repo_url != self.repo_url or snapshot.commit_sha != self.commit_sha:
        raise SourceReadError("引用与当前仓库或代码版本不一致。")
    excerpt = snapshot.read(file_path, start_line, end_line)
    # Partial giant lines must not be presented as complete source evidence.
    if excerpt.partial_last_line:
        if excerpt.end_line == excerpt.start_line:
            return excerpt.format() + "\nNo citation identifier: this line is only partially displayed."
        excerpt = replace(snapshot.read(file_path, start_line, excerpt.end_line - 1), truncated=True)
    if not excerpt.total_lines:
        return excerpt.format()
    source = check_source_citation(
        self.repo_root, self.repo_url, self.commit_sha, excerpt.file_path,
        excerpt.start_line, excerpt.end_line, excerpt.content, excerpt.file_sha256,
    )
    existing = next((item for item in self._sources.values() if item.model_dump(exclude={"reference_id"}) == source.model_dump()), None)
    reference = existing.reference_id if existing else f"S{self.reference_count + 1}"
    self._sources[reference] = CitedSource(**source.model_dump(), reference_id=reference)
    return f"[{reference}] Commit: {self.commit_sha}\n" + excerpt.format()

def check_answer(self, answer):
    citations, issues, resolved = [], [], {}

    def replace(match):
        reference = match[1]
        if reference not in resolved:
            source = self._sources.get(reference)
            if source is None:
                issues.append(CitationIssue(reference_id=reference, message="引用编号不存在。"))
                resolved[reference] = None
            else:
                try:
                    check_source_citation(
                        self.repo_root, self.repo_url, self.commit_sha, source.file_path,
                        source.start_line, source.end_line, source.source_text, source.file_sha256,
                    )
                except (ValueError, OSError):
                    issues.append(CitationIssue(reference_id=reference, message="引用源码已改变或无法核对。"))
                    resolved[reference] = None
                else:
                    citations.append(source)
                    resolved[reference] = source
        source = resolved[reference]
        # Source links always come from the verified snapshot, even if a model supplied a URL.
        return f"[{reference}]({source.url})" if source else f"[{reference}]"

    text = _map_prose(answer, lambda part: re.sub(r"(?<!\\)\[(S\d+)\](?:\([^\n)]*\))?", replace, part))
    if not resolved:
        issues.append(CitationIssue(message="回答未提供可核对的源码引用。"))
    return CheckedAnswer(text=text, citations=tuple(citations), issues=tuple(issues))

def find_in_snapshot(
    repo_root: str, repo_url: str, commit_sha: str, query: str,
    mode: SearchMode = "text", path_filter: str = "", case_sensitive: bool = False,
    limit: int = 20, offset: int = 0,
) -> SearchResult:
    """Literal substring matching only. Previews are locators, not checked citations."""
    if mode not in ("text", "path", "symbol"):
        raise ValueError("mode must be text, path or symbol.")
    if not isinstance(query, str) or not query.strip() or len(query) > 256 or any(char in query for char in "\x00\r\n"):
        raise ValueError("query must be nonempty, single-line text of at most 256 characters.")
    if not isinstance(path_filter, str) or len(path_filter) > 256 or any(char in path_filter for char in "\x00\r\n"):
        raise ValueError("path_filter must be single-line text of at most 256 characters.")
    if type(case_sensitive) is not bool:
        raise ValueError("case_sensitive must be a boolean.")
    if type(limit) is not int or not 1 <= limit <= 50 or type(offset) is not int or offset < 0:
        raise ValueError("limit must be 1–50 and offset must be a nonnegative integer.")
    snapshot = load_snapshot(repo_root)
    if snapshot.repo_url != normalize_repo_url(repo_url) or snapshot.commit_sha != commit_sha:
        raise SourceReadError("Search repository and snapshot version differ.")
    normalize = (lambda value: value) if case_sensitive else str.casefold
    needle, path_needle = normalize(query), normalize(path_filter)
    paths = (
        path for path in sorted(snapshot.files)
        if PurePosixPath(path).suffix.lower() in CODE_EXTENSIONS
        and not SKIP_DIRECTORIES.intersection(PurePosixPath(path).parts[:-1])
        and path_needle in normalize(path)
        and (mode != "symbol" or PurePosixPath(path).suffix.lower() == ".py")
    )

for path in paths:
    if scanned >= MAX_SCAN_FILES:
        scan_limited = True
        break
    scanned += 1
    if mode == "path":
        candidates = iter([SearchHit(file_path=path, kind="path")]) if needle in normalize(path) else iter(())
    else:
        size = snapshot.files[path]["bytes"]
        if size > MAX_FILE_BYTES:
            skip(path, "file_too_large")
            continue
        if bytes_read >= MAX_SCAN_BYTES or bytes_read + size > MAX_SCAN_BYTES:
            scan_limited = True
            break
        name, data = read_source_bytes(snapshot.root, path, min(MAX_FILE_BYTES, MAX_SCAN_BYTES - bytes_read))
        bytes_read += len(data)
        if name != path or hashlib.sha256(data).hexdigest() != snapshot.files[path]["sha256"]:
            raise SourceReadError("Snapshot source changed; search was not completed.")
        if b"\x00" in data:
            skip(path, "binary_file")
            continue
        text = data.decode("utf-8", errors="ignore")
        try:
            candidates = _hits_for_file(path, text, mode, lambda value: needle in normalize(value))
        except (SyntaxError, RecursionError):
            skip(path, "python_parse_error")
            continue
    for candidate in candidates:
        if seen >= offset:
            if len(hits) >= limit:
                has_more = True
                break
            hits.append(candidate)
        seen += 1
    if has_more:
        break
return SearchResult(
    repo_url=snapshot.repo_url, commit_sha=snapshot.commit_sha, query=query, mode=mode,
    hits=tuple(hits), offset=offset, limit=limit, next_offset=offset + len(hits) if has_more else None,
    scanned_files=scanned, skipped_count=skipped_count, skipped_examples=tuple(skipped), scan_limited=scan_limited,
)

